  'maintenance_income_thresholds', 'condition', true,
  'Person in Sweden: SEK 10,314 per month must remain after rent, for cohabiting partners', 'A RESIDUAL-INCOME TEST, NOT A SALARY BAR. Migrationsverket asks what is left after tax and rent, to cover food, clothing, hygiene, telephony and insurance for the whole household -- so a high salary with a high rent can still fail. SEK 6,243 is the single-adult figure; SEK 10,314 applies to cohabiting spouses or partners, which is the figure relevant to this route. Children add SEK 3,336 (0-6), 4,004 (7-10), 4,672 (11-14) or 5,339 (15+), reduced by any child allowance. Migrationsverket dates these to 2026, so they are revised.',
  null, null,
  null, '{"per_month_single_adult_sek":6243,"per_month_cohabiting_partners_sek":10314,"per_month_child_0_6_sek":3336,"per_month_child_7_10_sek":4004,"per_month_child_11_14_sek":4672,"per_month_child_15_plus_sek":5339,"currency":"SEK","stated_for_year":2026}'::jsonb,
