    order by s.visa_type_id nulls last
    limit 1),
  'in 2026, the amount you must have left over after tax and the rent is paid is: sek 6,243 for a single adult sek 10,314 for cohabiting spouses or cohabiting partners sek 3,336 for children 0–6 years of age sek 4,004 for children 7–10 years of age sek 4,672 for children 11–14 years of age sek 5,339 for children 15 years of age or older.', 'manual', 1.00,
